    tariffModel: {"kind":"questionTotal","notation":"(10 marks, 4 + 6)"}, totalMarks: 6,
    rows: [
    { id: "r-1", kind: "point", verbatim: "Reels: allow influencers to create and share short videos. They are typically 15 to 60 seconds long and can include music, text, stickers, and special effects. Reels are popular for showcasing creative and engaging content, including tutorials, challenges, and behind-the-scenes glimpses etc.", marks: null, openList: true },
    { id: "r-2", kind: "point", verbatim: "Endorsements: and collaborations occur when a social media influencer partners with a company to promote their services or products. The influencer uses their platform to create content that showcases or endorses the brand. This can be done through sponsored posts, videos, reels, stories etc.", marks: null, openList: true },
    { id: "r-3", kind: "point", verbatim: "Affiliate links: are unique URL’s provided to influencers by brands or affiliate programs. When the influencer shares the link with their audience they can click on it and make a discounted purchase. The influencer then earns a commission or a percentage of the sale for each audience purchase.", marks: null, openList: true },
    ],
